"""Printed 256–259: source ellipse examples and translated elements."""
import math
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_native_geometry import geometry,path
def graph(n):
 if n==17:h=k=0;ax=2;ay=3;s=45
 elif n==18:h=k=0;ax=math.sqrt(5);ay=math.sqrt(2);s=53
 elif n in [19,20]:h=1;k=1;ax=3 if n==19 else 1.7;ay=1.7 if n==19 else 3;s=38
 elif n==21:h=1;k=-2;ax=5;ay=2;s=32
 else:h=3;k=2;ax=4;ay=2;s=38
 ox=240-h*s;oy=185+k*s
 def pt(x,y):return(ox+s*x,oy-s*y)
 paths=[path([pt(h+ax*math.cos(t*math.pi/90),k+ay*math.sin(t*math.pi/90)) for t in range(181)]),path([(25,oy),(480,oy)]),path([(ox,20),(ox,345)])]
 c=math.sqrt(abs(ax*ax-ay*ay));vertical=ay>ax
 foci=[(h,k-c),(h,k+c)] if vertical else [(h-c,k),(h+c,k)]
 verts=[(h,k-ay),(h,k+ay)] if vertical else [(h-ax,k),(h+ax,k)]
 covers=[(h-ax,k),(h+ax,k)] if vertical else [(h,k-ay),(h,k+ay)]
 symbolic=n in [19,20]
 labels=[(240+7,185+23,'C(h,k)' if symbolic else f'C({h:g},{k:g})'),(482,oy+6,'x'),(ox,14,'y')]
 dots=[(h,k)]+foci+verts+covers
 for i,(x,y) in enumerate(foci+verts+covers):
  xx,yy=pt(x,y)
  if symbolic:
   names=(['F(h,k−c)','F(h,k+c)','V(h,k−a)','V(h,k+a)','(h−b,k)','(h+b,k)'] if vertical else ['F(h−c,k)','F(h+c,k)','V(h−a,k)','V(h+a,k)','(h,k−b)','(h,k+b)']);label=names[i]
  else:
   if n==17:label=['F(0,−√5)','F(0,√5)','V(0,−3)','V(0,3)','(−2,0)','(2,0)'][i]
   elif n==18:label=['F(−√3,0)','F(√3,0)','V(−√5,0)','V(√5,0)','(0,−√2)','(0,√2)'][i]
   elif n==21:label=['F(1−√21,−2)','F(1+√21,−2)','V(−4,−2)','V(6,−2)','(1,−4)','(1,0)'][i]
   else:label=f'({x:.3g},{y:.3g})'
  labels.append((max(6,xx-35),yy+23 if y<=k else yy-9,label))
 if n==17:
  for y in [-2,-1,1,2]:
   for sign in [-1,1]:
    x=sign*2*math.sqrt(1-y*y/9);dots.append((x,y));xx,yy=pt(x,y);labels.append((xx-85 if sign<0 else xx+6,yy+5,f'({"−" if sign<0 else ""}'+('4√2/3' if abs(y)==1 else '2√5/3')+f',{y})'))
 return geometry('Figure 9.'+str(n),'Figure 9.'+str(n)+' — native ellipse and exact '+('symbolic translated elements' if symbolic else 'source coordinates'),paths,labels,points=[{'x':pt(x,y)[0],'y':pt(x,y)[1]} for x,y in dots],size=(580,390))
def tangent_graph():
 # x²/9+y²/4=1, P=(-3/sqrt2,sqrt2); exact tangent and normal.
 q=(-3/math.sqrt(2),math.sqrt(2));s=48
 def pt(x,y):return(245+s*x,190-s*y)
 slope=2/3;normal=-1/slope
 paths=[path([pt(3*math.cos(i*math.pi/90),2*math.sin(i*math.pi/90)) for i in range(181)]),path([pt(-4,0),pt(4,0)]),path([pt(0,-3),pt(0,3)]),path([pt(x,q[1]+slope*(x-q[0])) for x in [-3.7,1]]),path([pt(x,q[1]+normal*(x-q[0])) for x in [-3.2,.6]])]
 return geometry('Figure 9.23','Figure 9.23 — tangent LM and perpendicular normal QR at an ellipse point',paths,[(94,107,'P'),(73,155,'L'),(250,27,'M'),(75,25,'Q'),(278,335,'R'),(441,195,'x'),(245,39,'y')],points=[{'x':pt(*q)[0],'y':pt(*q)[1]}],size=(510,390))
ORIGIN_TABLE={'type':'dataTable','headers':['Orientation','Foci','Vertices / semimajor axis','Semiminor axis'],'rows':[['Horizontal','(−c,0),(c,0)','(−a,0),(a,0)','(0,b),(0,−b)'],['Vertical','(0,c),(0,−c)','(0,−a),(0,a)','(b,0),(−b,0)'],['Relation','c²=a²−b²','a>b>0','']]}
SHIFT_TABLE={'type':'dataTable','headers':['Orientation','Foci','Vertices / major-axis endpoints','Minor-axis endpoints'],'rows':[['Horizontal','F₁(h−c,k),F₂(h+c,k)','V₁(h−a,k),V₂(h+a,k)','B₁(h,k+b),B₂(h,k−b)'],['Vertical','F₁(h,k+c),F₂(h,k−c)','V₁(h,k+a),V₂(h,k−a)','B₁(h+b,k),B₂(h−b,k)']]}
PAGES=[page('132_page_2.jpg',256,[ORIGIN_TABLE,heading('Example 10'),paragraph('Determine the vertices, end points of the minor axis and coordinates of foci of ellipse 9x²+4y²=36. Sketch the ellipse.'),heading('Solution'),paragraph('Rewrite in standard form:'),eq(r'9x^2+4y^2=36\quad\Rightarrow\quad\frac{9x^2}{36}+\frac{4y^2}{36}=1\quad\Rightarrow\quad\frac{x^2}{4}+\frac{y^2}{9}=1','38-a'),paragraph('Equation (38-a) is the vertical standard form (37). The center is at the origin, with vertices on the y-axis since the larger number is under y². Thus a²=9 or a=3, b²=4 or b=2 and c²=a²−b²=9−4=5 or c=±√5.'),eq(r'C(0,0),\quad V_1(0,3),V_2(0,-3),\quad B_1(2,0),B_2(-2,0),\quad F_1(0,\sqrt5),F_2(0,-\sqrt5)'),paragraph('For some points on the ellipse:'),eq(r'y=1:\quad\frac{x^2}{4}+\frac19=1\quad\Rightarrow\quad x=\pm\frac{4\sqrt2}{3}'),eq(r'y=2:\quad\frac{x^2}{4}+\frac49=1\quad\Rightarrow\quad x=\pm\frac{2\sqrt5}{3}'),paragraph('The ellipse is symmetrical with respect to major and minor axes. Center, vertices, foci, endpoints and the points (±4√2/3,±1),(±2√5/3,±2) are labelled to obtain the graph in Figure 9.17.'),graph(17),heading('Example 11'),paragraph('Determine vertices, minor-axis endpoints and foci of 2x²+5y²=10. Sketch the ellipse.'),heading('Solution'),eq(r'2x^2+5y^2=10\quad\Rightarrow\quad\frac{2x^2}{10}+\frac{5y^2}{10}=1\quad\Rightarrow\quad\frac{x^2}{5}+\frac{y^2}{2}=1\quad\Rightarrow\quad\frac{x^2}{(\sqrt5)^2}+\frac{y^2}{(\sqrt2)^2}=1','38-b'),note('The focal distance c is nonnegative √5; the two focal coordinates take its ± signs. Semiaxis lengths a and b are positive.')]),
page('133_page_1.jpg',257,[paragraph('Ellipse (38-b) is the horizontal form (36). The center is at the origin; vertices are on the x-axis since the larger number is under x². Thus a²=5 or a=√5, b²=2 or b=√2 and c²=a²−b²=5−2=3 or c=±√3. Its coordinates are:'),eq(r'C(0,0),\quad V_1(-\sqrt5,0),V_2(\sqrt5,0),\quad B_1(0,\sqrt2),B_2(0,-\sqrt2),\quad F_1(-\sqrt3,0),F_2(\sqrt3,0)'),graph(18),heading('(iv) Equation of an ellipse through its elements'),heading('Example 12'),paragraph('Find an equation for the ellipse with foci F₁(−1,0), F₂(1,0) and vertices V₁(−2,0), V₂(2,0).'),heading('Solution'),paragraph('By inspection center C(0,0), distance from center to vertex a=2 and to focus c=1. Insert a and c into:'),eq(r'b^2=a^2-c^2=4-1=3\quad\Rightarrow\quad b=\pm\sqrt3'),paragraph('Use a and b in the horizontal standard form (36):'),eq(r'\frac{x^2}{4}+\frac{y^2}{3}=1','39'),heading('(v) Standard form of equation of an ellipse'),paragraph('For center C(h,k), semimajor axis a and semiminor axis b, major axis parallel to the x-axis:'),eq(r'\frac{(x-h)^2}{a^2}+\frac{(y-k)^2}{b^2}=1,\quad a>b','40'),graph(19),paragraph('For center C(h,k), semimajor axis a and semiminor axis b, major axis parallel to the y-axis:'),eq(r'\frac{(x-h)^2}{b^2}+\frac{(y-k)^2}{a^2}=1,\quad a>b','41'),graph(20),note('Example 12’s semiminor length is √3, while its signed co-vertex coordinates are ±√3. Translated equations use a>b>0 for a noncircular ellipse.')]),
page('133_page_2.jpg',258,[heading('Example 13'),paragraph('Graph 4x²+25y²−8x+100y+4=0. Indicate center, vertices, foci and endpoints of minor axis.'),heading('Solution'),paragraph('Rewrite in standard form by completing square:'),eq(r'4x^2-8x+25y^2+100y=-4'),eq(r'4(x^2-2x+1)+25(y^2+4y)=0'),paragraph('Add and subtract 100 to obtain:'),eq(r'4(x^2-2x+1)+25(y^2+4y+4)=100'),eq(r'4(x-1)^2+25(y+2)^2=100'),eq(r'\frac{4(x-1)^2}{100}+\frac{25(y+2)^2}{100}=1\quad\Rightarrow\quad\frac{(x-1)^2}{25}+\frac{(y+2)^2}{4}=1','42'),paragraph('Substitution X=x−h=x−1 and Y=y−k=y+2, h=1, k=−2 gives the translated ellipse in the XY-plane:'),eq(r'\frac{X^2}{25}+\frac{Y^2}{4}=1','43'),paragraph('The center of the ellipse is at the origin. The major axis is horizontal and vertices are on the x-axis. Thus a=5, b=2 and c=±√21=±4.58. Coordinates of the translated ellipse (43) are:'),eq(r'C(0,0),\quad V_1(-5,0),V_2(5,0),\quad B_1(0,2),B_2(0,-2),\quad F_1(-4.58,0),F_2(4.58,0)'),paragraph('The center C(0,0) of the translated ellipse has X=0,Y=0. Put these values in (43) to obtain the coordinates of the given ellipse (42):'),eq(r'X=x-1\quad\Rightarrow\quad0=x-1\quad\Rightarrow\quad x=1,\quad Y=y+2\quad\Rightarrow\quad0=y+2\quad\Rightarrow\quad y=-2'),paragraph('The center of the given ellipse is C(1,−2). For the translated vertex V₁(−5,0), X=−5,Y=0; for V₂, X=5,Y=0. Put these in (43) to obtain the given vertices:'),eq(r'X=x-1\quad\Rightarrow\quad-5=x-1\quad\Rightarrow\quad x=-4,\quad Y=y+2\quad\Rightarrow\quad0=y+2\quad\Rightarrow\quad y=-2'),graph(21),note('The origin center and unshifted vertices/foci here belong to the XY system only. In the original xy system, center is (1,−2), vertices (−4,−2),(6,−2), co-vertices (1,0),(1,−4), and exact foci (1±√21,−2). Source focal coordinates −3.58,5.58 are rounded. Recovering x=X+1,y=Y−2 uses the translation definitions, rather than substituting into equation (43) alone.')]),
page('134_page_1.jpg',259,[paragraph('The vertex V₁ of ellipse (42) is V₁(−4,−2) and V₂ is V₂(6,−2). For the translated foci F₁(−4.58,0),F₂(4.58,0), put X=−4.58,Y=0 (and X=4.58,Y=0) in (43) to obtain:'),eq(r'X=x-1\quad\Rightarrow\quad-4.58=x-1\quad\Rightarrow\quad x=-3.58,\quad Y=y+2\quad\Rightarrow\quad0=y+2\quad\Rightarrow\quad y=-2'),paragraph('The focus F₁ is F₁(−3.58,−2) and F₂ is F₂(5.58,−2). The graph is shown in Figure 9.21. Orientation with center C(h,k) and vertices/endpoints of the major and minor axes is summarized:'),SHIFT_TABLE,eq(r'b^2=a^2-c^2\quad\mathrm{or}\quad c^2=a^2-b^2,\quad a>b>0'),heading('Example 14'),paragraph('Find the equation of the ellipse with vertices (−1,2),(7,2) and 2 as the length of the semiminor axis.'),heading('Solution'),paragraph('The center is at the midpoint of V₁V₂, (3,2), or C(h,k)=C(3,2). The distance from center to either vertex is a=4 units, and b=2. The major axis is parallel to the x-axis. Use horizontal form (40):'),eq(r'\frac{(x-h)^2}{a^2}+\frac{(y-k)^2}{b^2}=1'),eq(r'\frac{(x-3)^2}{16}+\frac{(y-2)^2}{4}=1,\quad C(h,k)=(3,2),\quad a=4,\ b=2','44'),graph(22),heading('(vi) Recognition of tangent and normal to an ellipse'),heading('A. Tangent to an ellipse'),paragraph('“A line that interacts the ellipse at a point is known as tangent at the ellipse”. In Figure 9.23, line LM is tangent to the ellipse, intersecting the ellipse at point P.'),heading('B. Normal to an ellipse'),paragraph('Normal to an ellipse is a line perpendicular to the tangent to curve through the point of contact. Line QR is normal to the ellipse, perpendicular to tangent LM at point P in Figure 9.23.'),tangent_graph(),note('A tangent to a nondegenerate ellipse meets it in one real contact point, with multiplicity two. Merely passing through a point of the ellipse does not imply tangency. The normal is perpendicular at that contact and usually does not pass through the center. The native Figure 9.23 uses an actual ellipse point with perpendicular tangent/normal to illustrate the source geometry.')])]
for v in PAGES:v.update(title='CONICS-II',visualStatus='Full origin/translated ellipse tables and examples, six exact graphs and tangent/normal diagram',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':(v['page']+9)//2,'side':'left' if v['page']%2 else 'right','reason':'Every source coordinate, denominator and translation step visually checked'})
EXAMPLES=[]
for n,q,steps,ans,start,end in [
('10','Find vertices, minor-axis endpoints and foci of 9x²+4y²=36, and sketch.',['Divide by 36 to obtain x²/4+y²/9=1.','The larger denominator 9 is under y², so the major axis is vertical; a=3,b=2.','Compute c=√(a²−b²)=√5.','Center is (0,0); vertices (0,±3); minor-axis endpoints (±2,0); foci (0,±√5).','For y=±1 the x values are ±4√2/3; for y=±2 they are ±2√5/3. Plot these with the axis intercepts and draw the symmetric closed curve.','The vertices give focal-distance sum 6=2a, and the plotted points satisfy the standard equation.'],'C(0,0), V(0,±3), co-vertices (±2,0), F(0,±√5).',256,256),
('11','Find vertices, minor-axis endpoints and foci of 2x²+5y²=10, and sketch.',['Divide by 10: x²/5+y²/2=1.','The larger denominator 5 is under x², so a=√5,b=√2 and the major axis is horizontal.','Compute c=√(5−2)=√3.','Center is (0,0), vertices (±√5,0), minor-axis endpoints (0,±√2), foci (±√3,0).','Plot the center, these four axis endpoints and foci; connect the endpoints with a smooth symmetric ellipse.','All intercepts satisfy the equation; c²+b²=3+2=5=a², checking the foci.'],'C(0,0), V(±√5,0), co-vertices (0,±√2), F(±√3,0).',256,257),
('12','Find the ellipse with foci (−1,0),(1,0) and vertices (−2,0),(2,0).',['Both focal and vertex pairs have midpoint (0,0).','The major axis lies on the x-axis, with semimajor length a=2.','The distance from center to either focus is c=1.','Compute b²=a²−c²=4−1=3, so b=√3.','Use horizontal standard form: x²/4+y²/3=1.','At the vertices the distances to the foci sum to 1+3=4=2a, confirming the stated elements.'],'x²/4+y²/3=1.',257,257),
('13','Graph 4x²+25y²−8x+100y+4=0; identify center, vertices, foci and minor endpoints.',['Group terms: 4(x²−2x)+25(y²+4y)=−4.','Complete squares: 4[(x−1)²−1]+25[(y+2)²−4]=−4.','Thus 4(x−1)²+25(y+2)²=100, or (x−1)²/25+(y+2)²/4=1.','Center is (1,−2); a=5,b=2,c=√21, major axis horizontal.','Vertices are (1±5,−2)=(−4,−2),(6,−2); minor endpoints (1,−2±2)=(1,0),(1,−4).','Foci are (1±√21,−2), approximately (−3.5826,−2),(5.5826,−2).','Plot these elements and a smooth ellipse. Expand the completed-square equation to recover the original coefficients, checking the translation.'],'C(1,−2), vertices (−4,−2),(6,−2), co-vertices (1,0),(1,−4), foci (1±√21,−2).',258,259),
('14','Find the ellipse with vertices (−1,2),(7,2) and semiminor length 2.',['The vertex midpoint is C=((−1+7)/2,(2+2)/2)=(3,2).','The vertices lie on a horizontal line, so the major axis is parallel to x.','The center-to-vertex distance is a=4; the given b=2.','Use (x−h)²/a²+(y−k)²/b²=1.','Substitute to obtain (x−3)²/16+(y−2)²/4=1.','Both vertices satisfy the equation, and the minor endpoints are (3,0),(3,4), 2 units from the center.'],'(x−3)²/16+(y−2)²/4=1.',259,259)]:
 e={'num':n,'title':'Ellipse Elements','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':pg,'jpg':f'{(pg+9)//2:03d}_page_{1 if pg%2 else 2}.jpg','verification':'All source elements and worked algebra visually checked'} for pg in range(start,end+1)]}
 if n in ['10','11','13','14']:e['sourceQuestionBlocks']=[graph({'10':17,'11':18,'13':21,'14':22}[n])]
 EXAMPLES.append(e)
